import { ChangeDetectionStrategy, Component } from '@angular/core';
import { RawMaterialService } from '../../services/raw-material-service';
import { FormGroup, FormBuilder, Validators, ReactiveFormsModule, FormsModule } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-edit-raw-material',
  imports: [CommonModule, ReactiveFormsModule, FormsModule],
  templateUrl: './edit-raw-material.html',
  styleUrl: './edit-raw-material.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EditRawMaterial {
rawMaterialForm! : FormGroup;
rawMaterialId! : number;
isLoading = true;

constructor(
    private fb: FormBuilder,
    private service: RawMaterialService,
    private route: ActivatedRoute,
    private router: Router
  ) {}

    ngOnInit(): void {
    this.rawMaterialForm = this.fb.group({
      name: ['', Validators.required],
      price: [''],
    });
   const id = Number(this.route.snapshot.paramMap.get('id'));
    if (id) {
      this.rawMaterialId = id;
      this.service.getProductByID(id).subscribe(product => {
        this.rawMaterialForm.patchValue(product); 
        this.isLoading = false;
      });
    } else {
      this.isLoading = false;
    }
    }
    onCancel(){
    this.resetForm();
    this.router.navigate(['/raw-material']);
  }
   onSubmit() {
  if (this.rawMaterialForm.invalid) 
    return;

   const dto = {
    ...this.rawMaterialForm.value,
   }

  console.log("Submitting Raw Material:", dto);

  this.service.updateProduct(this.rawMaterialId, dto).subscribe({
    next: () => {
      alert('✅ Product updated successfully');
      this.resetForm();
    },
    error: (err) => {
      console.error('❌ Upload failed', err);
      alert(err.error?.message || 'Upload failed. Please try again.');
    }
  });

  this.router.navigate(['/raw-material'])
}


  private resetForm() {
    this.rawMaterialForm.reset();
  }
}
